describe('Async Image Upload Progress', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Adjust the URL to your application's upload page
    });

    it('should show progress percentage during image upload', () => {
        const fileName = 'test-image.jpg'; // Ensure this file exists in the fixtures
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(fileName);
            cy.intercept('POST', '/upload', (req) => {
                req.on('response', (res) => {
                    res.send({ status: 'success', url: 'http://example.com/image.jpg' });
                });
            }).as('uploadImage');

            cy.get('button[type="submit"]').click();
            cy.wait('@uploadImage');

            cy.get('.progress-bar').should('be.visible');
            cy.get('.progress-percentage').should('contain', '100%');
        });
    });

    it('should handle upload failure gracefully', () => {
        const fileName = 'test-image.jpg'; // Ensure this file exists in the fixtures
        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(fileName);
            cy.intercept('POST', '/upload', {
                statusCode: 500,
                body: { error: 'Upload failed' }
            }).as('uploadImageFail');

            cy.get('button[type="submit"]').click();
            cy.wait('@uploadImageFail');

            cy.get('.error-message').should('be.visible').and('contain', 'Upload failed');
            cy.get('.progress-bar').should('not.exist');
        });
    });
});
